# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

# This rule honours Kubernetes precedence: pod.spec.automountServiceAccountToken
# overrides serviceAccount.automountServiceAccountToken. It alerts only on
# workloads that will actually mount a token (pod-level true, or pod-level
# unset with an SA that does not explicitly disable).

# POD
deny contains msga if {
	start_of_path := "spec."
	pod := input[_]
	pod.kind == "Pod"

	wl_namespace := pod_namespace(pod)
	result := is_sa_auto_mounted(pod.spec, start_of_path, wl_namespace)
	failed_path := get_failed_path(result)
	fixed_path := get_fixed_path(result)

	msga := {
		"alertMessage": sprintf("Pod: %v in the following namespace: %v mounts service account tokens by default", [pod.metadata.name, wl_namespace]),
		"alertScore": 9,
		"packagename": "armo_builtins",
		"fixPaths": fixed_path,
		"failedPaths": failed_path,
		"alertObject": {"k8sApiObjects": [pod]},
	}
}

# WORKLOADS: Deployment / ReplicaSet / DaemonSet / StatefulSet / Job
deny contains msga if {
	start_of_path := "spec.template.spec."
	spec_template_spec_patterns := {"Deployment", "ReplicaSet", "DaemonSet", "StatefulSet", "Job"}
	wl := input[_]
	spec_template_spec_patterns[wl.kind]

	wl_namespace := pod_namespace(wl)
	result := is_sa_auto_mounted(wl.spec.template.spec, start_of_path, wl_namespace)
	failed_path := get_failed_path(result)
	fixed_path := get_fixed_path(result)

	msga := {
		"alertMessage": sprintf("%v: %v in the following namespace: %v mounts service account tokens by default", [wl.kind, wl.metadata.name, wl_namespace]),
		"alertScore": 7,
		"packagename": "armo_builtins",
		"fixPaths": fixed_path,
		"failedPaths": failed_path,
		"alertObject": {"k8sApiObjects": [wl]},
	}
}

# CRONJOB
deny contains msga if {
	start_of_path := "spec.jobTemplate.spec.template.spec."
	wl := input[_]
	wl.kind == "CronJob"

	wl_namespace := pod_namespace(wl)
	result := is_sa_auto_mounted(wl.spec.jobTemplate.spec.template.spec, start_of_path, wl_namespace)
	failed_path := get_failed_path(result)
	fixed_path := get_fixed_path(result)

	msga := {
		"alertMessage": sprintf("%v: %v in the following namespace: %v mounts service account tokens by default", [wl.kind, wl.metadata.name, wl_namespace]),
		"alertScore": 7,
		"packagename": "armo_builtins",
		"fixPaths": fixed_path,
		"failedPaths": failed_path,
		"alertObject": {"k8sApiObjects": [wl]},
	}
}

# ----- decision helpers -----

# Branch 1: pod spec explicitly sets automountServiceAccountToken: true.
# Pod-level wins over SA, so this always mounts. Fix by setting the pod
# field to false - deleting it is unsafe because it falls back to the SA,
# which may also enable auto-mount.
is_sa_auto_mounted(spec, start_of_path, wl_namespace) := [failed_path, fix_path] if {
	spec.automountServiceAccountToken == true

	failed_path := sprintf("%vautomountServiceAccountToken", [start_of_path])
	fix_path := {"path": sprintf("%vautomountServiceAccountToken", [start_of_path]), "value": "false"}
}

# Branch 2: pod spec does not set automountServiceAccountToken, and the
# referenced SA exists and does not explicitly disable auto-mount. Token
# will mount by default. Fix by setting pod-level to false.
is_sa_auto_mounted(spec, start_of_path, wl_namespace) := [failed_path, fix_path] if {
	failed_path := ""
	fix_path := {"path": sprintf("%vautomountServiceAccountToken", [start_of_path]), "value": "false"}
	not spec.automountServiceAccountToken == false
	not spec.automountServiceAccountToken == true

	sa := input[_]
	sa.kind == "ServiceAccount"
	is_same_sa(spec, sa.metadata.name)
	is_same_namespace(sa.metadata.namespace, wl_namespace)
	not sa.automountServiceAccountToken == false

}

# Branch 3: pod spec does not set automountServiceAccountToken, and no
# matching SA is in the input (YAML scan, or SA not scanned). Kubernetes
# default is to mount, so flag it.
is_sa_auto_mounted(spec, start_of_path, wl_namespace) := [failed_path, fix_path] if {
	not spec.automountServiceAccountToken == false
	not spec.automountServiceAccountToken == true

	not matching_sa_exists(spec, wl_namespace)

	fix_path := {"path": sprintf("%vautomountServiceAccountToken", [start_of_path]), "value": "false"}
	failed_path := ""
}

# No branch when spec.automountServiceAccountToken == false: pod-level
# disable wins over any SA setting, so no deny.

matching_sa_exists(spec, wl_namespace) if {
	sa := input[_]
	sa.kind == "ServiceAccount"
	is_same_sa(spec, sa.metadata.name)
	is_same_namespace(sa.metadata.namespace, wl_namespace)
}

get_failed_path(paths) := [paths[0]] if {
	paths[0] != ""
} else := []

get_fixed_path(paths) := [paths[1]] if {
	paths[1] != ""
} else := []

# ----- matching helpers -----

pod_namespace(obj) := ns if {
	ns := obj.metadata.namespace
} else := "default"

is_same_sa(spec, serviceAccountName) if {
	spec.serviceAccountName == serviceAccountName
}

is_same_sa(spec, serviceAccountName) if {
	not spec.serviceAccountName
	serviceAccountName == "default"
}

is_same_namespace(ns1, ns2) if {
	ns1 == ns2
}

is_same_namespace(ns1, ns2) if {
	not ns1
	ns2 == "default"
}

is_same_namespace(ns1, ns2) if {
	not ns2
	ns1 == "default"
}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

deny contains msga if {
	workload_kinds := {"Deployment", "ReplicaSet", "DaemonSet", "StatefulSet", "Job", "Pod", "CronJob"}
	workload := input[_]
	workload_kinds[workload.kind]

	networkpolicies := [networkpolicy | networkpolicy = input[_]; is_network_policy(networkpolicy)]
	not connected_to_any_network_policy(workload, networkpolicies)

	msga := {
		"alertMessage": sprintf("%v: no networkpolicy configured in labels", [workload.metadata.name]),
		"packagename": "armo_builtins",
		"failedPaths": [],
		"fixPaths": [],
		"alertObject": {"k8sApiObjects": [workload]},
	}
}

# Helper function to identify all network policy types
is_network_policy(policy) if {
	policy.kind == "NetworkPolicy"
}

is_network_policy(policy) if {
	policy.kind == "CiliumNetworkPolicy"
}

is_network_policy(policy) if {
	policy.kind == "CiliumClusterwideNetworkPolicy"
}

# Returns the list of CiliumNetworkPolicySpec entries, unifying the
# `spec:` (single) and `specs:` (list) forms documented for CNP/CCNP CRDs.
# Either field may be present; both is also legal in Cilium.
cilium_policy_specs(policy) := specs if {
	from_spec := [s | s := policy.spec]
	from_specs := object.get(policy, "specs", [])
	specs := array.concat(from_spec, from_specs)
}

connected_to_any_network_policy(workload, networkpolicies) if {
	connected_to_network_policy(workload, networkpolicies[_])
}

# --- Cilium endpointSelector match (shared across pod/workload/cronjob) ---

# Cilium matches an endpointSelector against endpoint identity labels, which
# include the reserved key io.kubernetes.pod.namespace (derived from the pod's
# namespace, never present in pod.metadata.labels). Add both its key forms.
cilium_identity_labels(namespaced_metadata, template_metadata) := labels if {
	namespace := object.get(namespaced_metadata, "namespace", "default")
	labels := object.union(object.get(template_metadata, "labels", {}), {
		"io.kubernetes.pod.namespace": namespace,
		"k8s:io.kubernetes.pod.namespace": namespace,
	})
}

# matchLabels with keys: every key on the selector must equal the corresponding label.
cilium_endpoint_selector_matches(spec, labels) if {
	count(spec.endpointSelector.matchLabels) > 0
	count({x | spec.endpointSelector.matchLabels[x] == labels[x]}) == count(spec.endpointSelector.matchLabels)
}

# Selects-all: covers `endpointSelector: {}` and `endpointSelector: { matchLabels: {} }`.
# A non-empty matchExpressions makes the selector selective, NOT match-all
# (per Kubernetes LabelSelector: matchLabels AND matchExpressions must both match).
cilium_endpoint_selector_matches(spec, _) if {
	count(object.get(spec.endpointSelector, "matchLabels", {})) == 0
	count(object.get(spec.endpointSelector, "matchExpressions", [])) == 0
}

# --- Workload connection checks (Deployment, ReplicaSet, DaemonSet, StatefulSet, Job) ---

# Standard NetworkPolicy with podSelector (with labels)
connected_to_network_policy(wl, networkpolicy) if {
	workload_kinds := {"Deployment", "ReplicaSet", "DaemonSet", "StatefulSet", "Job"}
	workload_kinds[wl.kind]
	is_same_namespace(networkpolicy.metadata, wl.metadata)
	networkpolicy.kind == "NetworkPolicy"
	count(networkpolicy.spec.podSelector) > 0
	count({x | networkpolicy.spec.podSelector.matchLabels[x] == wl.spec.template.metadata.labels[x]}) == count(networkpolicy.spec.podSelector.matchLabels)
}

# CiliumNetworkPolicy
connected_to_network_policy(wl, networkpolicy) if {
	workload_kinds := {"Deployment", "ReplicaSet", "DaemonSet", "StatefulSet", "Job"}
	workload_kinds[wl.kind]
	is_same_namespace(networkpolicy.metadata, wl.metadata)
	networkpolicy.kind == "CiliumNetworkPolicy"
	spec := cilium_policy_specs(networkpolicy)[_]
	cilium_endpoint_selector_matches(spec, cilium_identity_labels(wl.metadata, wl.spec.template.metadata))
}

# CiliumClusterwideNetworkPolicy (no namespace check)
connected_to_network_policy(wl, networkpolicy) if {
	workload_kinds := {"Deployment", "ReplicaSet", "DaemonSet", "StatefulSet", "Job"}
	workload_kinds[wl.kind]
	networkpolicy.kind == "CiliumClusterwideNetworkPolicy"
	spec := cilium_policy_specs(networkpolicy)[_]
	cilium_endpoint_selector_matches(spec, cilium_identity_labels(wl.metadata, wl.spec.template.metadata))
}

# --- Pod connection checks ---

# Standard NetworkPolicy with podSelector (with labels)
connected_to_network_policy(wl, networkpolicy) if {
